# These source errors concern the visible section numbers. The reference
# metadata does not print a heading number; retain a complete heading in each
# branch and override the number while the printed heading runs.
for number,title,correct in [
    (837,r"Algebraicity of $\widehat{\varphi}$: preliminary verification over a trait",'1.2.12'),
    (839,r"Algebraicity of $\widehat{\varphi}$",'1.2.13')]:
    wrong=correct.replace('1.2.','1.2.2.');label='XVIII.subsubsec'+correct
    new=r'\subsubsection{'+title+r'}\etiquette['+correct+']{'+label+'}'
    old=(r'\let\SGAsavedsubsubsection\thesubsubsection'+'\n'
         +r'\renewcommand{\thesubsubsection}{'+wrong+'}\n'
         +r'\subsubsection{'+title+r'}\etiquette['+wrong+']{'+label+'}\n'
         +r'\let\thesubsubsection\SGAsavedsubsubsection')
    PAIRS[number]=(old,new)
    INTERMEDIATE[number]=r'\subsubsection{'+title+'}'+correct+'{'+label+'}'

def main(target_name='EN_T3_EXACT_PAIRS.json'):
    master=(ROOT/'output/en/SGA4_EN_annotated_master.tex').read_text()
    text=select_inline_variants(master,True).split(r'\backmatter',1)[0]
    mps=json.loads((ROOT/'sources/fixes/MISPRINTS_4.json').read_text());out=[];failed=[]
    for num in sorted(set(PAIRS)|set(SAME)):
        r=mps[num-1];ident=f'MP{num:04d}';w=page_window(text,r['expose'],r['page'],0 if num==831 else 1)
        local=text[w[0]:w[1]] if w else ''
        row=dict(id=ident,expose=r['expose'],page=r['page'],source='fixes/MISPRINTS_4.json#'+ident,
                 printed_french=r['print'],corrected_french=r['correct'],place=r['where'])
        if num in SAME:
            anchor,reason=SAME[num];hits=find_matches(anchor,local)
            row.update(assessment='no English impact',reason=reason,english_reading=anchor,location_verified=bool(hits),hits=len(hits))
            if not hits:failed.append(ident)
        else:
            pairs=PAIRS[num];pairs=pairs if isinstance(pairs,list) else [pairs];ds=[]
            for old,new in pairs:
                hits=[(a,b,'printed') for a,b in find_matches(old,local)]+[(a,b,'corrected') for a,b in find_matches(new,local)]
                hits=[h for h in hits if not any(h[0]>=z[0] and h[1]<=z[1] and h[1]-h[0]<z[1]-z[0] for z in hits)]
                if not hits and num in INTERMEDIATE:
                    hits=[(a,b,'source intermediate reading') for a,b in find_matches(INTERMEDIATE[num],local)]
                d=dict(printed=old,corrected=new,location_verified=len(hits)==1,hits=len(hits))
                if num in INTERMEDIATE:d['baseline_anchor']=INTERMEDIATE[num]
                if len(hits)==1:
                    a,b,state=hits[0];d.update(current_anchor=local[a:b],current_state=state,
                       context_before=local[max(0,a-100):a],context_after=local[b:b+100])
                else:failed.append(ident)
                ds.append(d)
            row.update(assessment='English-impact',reason='The exact English occurrence has been read against the canonical French record; the pair retains the released vocabulary and all independent source corrections.',english_deltas=ds)
            if len(ds)==1:row['english_delta']=ds[0]
        out.append(row)
    target=ROOT/'output/shared'/target_name;temporary=target.with_suffix('.tmp')
    temporary.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');temporary.replace(target)
    print('Reviewed',len(out),'no-impact',len(SAME),'impact',len(PAIRS),'unlocated',failed)

if __name__=='__main__':main()
